from pathlib import Path
import hashlib, json
root = Path('products/services/sqlite-repair/bespoke-inbound')
for path in sorted(root.rglob('*')):
    if not path.is_file() or path.suffix not in {'.md', '.json'}:
        continue
    name = path.name.lower()
    if not any(term in name for term in ('quote', 'terms', 'fictional-reply-control')):
        continue
    raw = path.read_bytes()
    print(json.dumps({'path': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'bytes': len(raw)}))
    if len(raw) <= 7500:
        print(raw.decode('utf-8'))
